from pathlib import Path
import json,zipfile,hashlib,html
from PIL import Image,ImageDraw,ImageFont
R=Path(__file__).resolve().parent.parent
S=json.loads((R/'scenes.json').read_text())
CSS='''*{box-sizing:border-box}body{margin:0;background:#f5f6f1;color:#222b22;font:15px/1.6 Inter,Arial,sans-serif}a{color:inherit}header{background:#222b22;color:white;padding:28px 35px}header h1{font-size:30px;margin:8px 0}header p{color:#d4decf;margin:0}nav{display:flex;gap:14px;flex-wrap:wrap}nav a,button,select{font:inherit;padding:9px 14px;background:white;border:1px solid #708064;border-radius:4px;color:#222b22}main{padding:30px 35px}h2{font-size:30px;line-height:1.2}.layout{display:grid;grid-template-columns:230px minmax(0,1fr)}aside{padding:22px;background:white;border-right:1px solid #cdd3c6}aside a{display:block;padding:9px 5px;font-size:13px}.scene{display:none}.scene.active{display:block}.devices{display:grid;grid-template-columns:1440fr 834fr 390fr;gap:20px;align-items:start}figure{margin:0;min-width:0}figure img{width:100%;height:auto;display:block;border:1px solid #cdd3c6}figcaption{font-size:12px;margin:8px 0}.tools{margin:20px 0}.note{font-size:13px;padding:17px;background:#e5e9dd;margin:18px 0 25px}.devicebar{display:flex;gap:10px;margin:22px 0}body[data-device=desktop] .devices,body[data-device=tablet] .devices,body[data-device=mobile] .devices{display:block}body[data-device=desktop] figure:not([data-device=desktop]),body[data-device=tablet] figure:not([data-device=tablet]),body[data-device=mobile] figure:not([data-device=mobile]){display:none}body[data-device=tablet] figure{max-width:834px}body[data-device=mobile] figure{max-width:390px}footer{padding:22px 35px;border-top:1px solid #cdd3c6;font-size:12px}@media(max-width:800px){header,main{padding:22px 20px}.layout{display:block}aside{display:none}.devices{grid-template-columns:1fr}.devicebar{flex-wrap:wrap}}'''
nav=''.join(f'<a href="#{s["id"]}" data-scene="{s["id"]}">{s["id"][:2]} · {s["title"]}</a>'for s in S)
scenes=''
for s in S:
 figures=''.join(f'<figure data-device="{d}"><figcaption>{d.title()} · {w} × {h} CSS px</figcaption><a href="images/{s["id"]}-{d}.png"><img src="images/{s["id"]}-{d}.png" alt="{html.escape(s["title"])} {d}"></a></figure>'for d,w,h in [('desktop',1440,1000),('tablet',834,1112),('mobile',390,844)])
 scenes+=f'<section class="scene" id="{s["id"]}"><h2>{s["id"][:2]} / {s["title"]}</h2><p>{s["purpose"]}</p><nav class="tools"><a href="source/{s["id"]}.html">Responsive source</a><a href="boards/{s["id"]}.png">Three-device board</a></nav><div class="devices">{figures}</div></section>'
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trailmark · 45-image storybook</title><style>@font-face{{font-family:Inter;src:url(assets/inter-400.ttf)}}{CSS}</style><body data-device="all"><header><div>LETBUYY / TRAILMARK / RIDE</div><h1>Make room for a game.</h1><p>15 connected scenes · 45 independent PNGs · 15 device boards</p></header><div class="layout"><aside>{nav}</aside><main><nav><a href="Trailmark-45-mockups.zip">Download 45 PNGs</a><a href="prototype-index.html">Source index</a><a href="README.md">Handoff & limitations</a><a href="comparisons/index.html">Research & neutral comparisons</a></nav><div class="note">Visual implementation target v1. Fictional catalog, account and mock-provider states. No production installation, live login, order or payment. Home scenes form one home; product scenes form one PDP.</div><div class="devicebar"><button data-device="all">All devices</button><button data-device="desktop">Desktop</button><button data-device="tablet">Tablet</button><button data-device="mobile">Mobile</button><select aria-label="Choose scene" id="scene-picker">{''.join(f'<option value="{s["id"]}">{s["id"][:2]} · {s["title"]}</option>'for s in S)}</select></div>{scenes}</main></div><footer>Original imagery via built-in image_gen · Native Inter text · Lucide React icons · 23 October 2026 · Design artifact, pending implementation.</footer><script>function show(id){{document.querySelectorAll('.scene').forEach(e=>e.classList.toggle('active',e.id===id));document.querySelector('#scene-picker').value=id;}}document.querySelectorAll('[data-scene]').forEach(a=>a.onclick=()=>show(a.dataset.scene));document.querySelectorAll('button[data-device]').forEach(b=>b.onclick=()=>document.body.dataset.device=b.dataset.device);document.querySelector('#scene-picker').onchange=e=>{{location.hash=e.target.value;show(e.target.value)}};show(location.hash.slice(1)||'{S[0]["id"]}');window.onhashchange=()=>show(location.hash.slice(1)||'{S[0]["id"]}');</script></body></html>'''
(R/'index.html').write_text(page)
(R/'prototype-index.html').write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trailmark responsive source</title><style>{CSS}</style><header><h1>Trailmark / Responsive source</h1><p>Native HTML/CSS presentation. No commerce requests.</p></header><main>'+''.join(f'<p><a href="source/{s["id"]}.html">{s["id"]} · {s["title"]}</a> — {s["route"]}</p>'for s in S)+'<p><a href="source/attribute-model.html">Additional category model / recovery state sheet</a></p><p><a href="index.html">Back to gallery</a></p></main></html>')
if not list((R/'images').glob('*.png')):print('Gallery ready; boards and ZIP await captures.');raise SystemExit
fontbase=R/'assets'
font=ImageFont.truetype(str(fontbase/'inter-600.ttf'),23)
small=ImageFont.truetype(str(fontbase/'inter-400.ttf'),16)
for s in S:
 thumbs=[]
 for d,w in [('desktop',864),('tablet',500),('mobile',234)]:
  im=Image.open(R/'images'/f'{s["id"]}-{d}.png').convert('RGB');im=im.resize((w,round(im.height*w/im.width)),Image.Resampling.LANCZOS);thumbs.append((d,im))
 height=max(im.height for d,im in thumbs)+180
 board=Image.new('RGB',(1720,height),'#f5f6f1');draw=ImageDraw.Draw(board);draw.text((35,25),'TRAILMARK / '+s['id'][:2]+' / '+s['title'],fill='#222b22',font=font);draw.text((35,65),'Independent responsive renders · DPR 1 · Full-page PNGs · Visual prototype',fill='#53604c',font=small)
 x=35
 for d,im in thumbs:
  draw.text((x,106),d.title(),font=small,fill='#53604c');board.paste(im,(x,137));x+=im.width+25
 board.save(R/'boards'/f'{s["id"]}.png')
with zipfile.ZipFile(R/'Trailmark-45-mockups.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in sorted((R/'images').glob('*.png')):z.write(p,'images/'+p.name)
print('Gallery, 15 boards and 45-PNG ZIP packaged.')
